/* =============================================================================
   PersonalDB · 14 · Job Portal: the catalogue of professions, skills and sub-skills
   -----------------------------------------------------------------------------
   Run AFTER 13_Jobs_Skill_Ratings.sql, in the Personal DB. SAFE TO RE-RUN:
   only the rows that are missing are added; nothing is changed or removed.
   Run it AGAIN every time script 03 is run again: 03 re-creates sp_Skill_Suggest.

   The data comes from professions_skills_subskills.xlsx (sheet "Profession
   Skill Subskills": group, profession, skill, sub-skill). A sub-skill written as
   "Structural Design: read drawings" is kept as "Read drawings" under its skill.
   The sub-skills of a skill are those of every profession that has it.

     jobs.CatalogGroups            profession groups
     jobs.CatalogProfessions       professions, each in one group
     jobs.CatalogSkills            skill names
     jobs.CatalogProfessionSkills  the skills of a profession, in order
     jobs.CatalogSubSkills         the sub-skills of a skill, in order

     jobs.sp_Catalog_SubSkills     the sub-skills of a skill, by its name
     jobs.sp_Skill_Suggest         the catalogue skills first, then the names at
                                   least two people have (as in script 03)

   The catalogue is the same for everybody: it has no UserId. The procedures
   take @UserId first like everywhere in schema jobs, and do not use it.
   ============================================================================= */
SET NOCOUNT ON;
SET XACT_ABORT ON;
SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
SET NOEXEC OFF;
GO

IF DB_NAME() IN ('master', 'model', 'msdb', 'tempdb') OR OBJECT_ID('dbo.SchemaInfo') IS NULL OR OBJECT_ID('jobs.SubSkills') IS NULL
BEGIN
    RAISERROR('Select the Personal DB and run 13_Jobs_Skill_Ratings.sql in it before running this script.', 16, 1);
    SET NOEXEC ON;
END
GO

IF NOT EXISTS (SELECT 1 FROM dbo.SchemaInfo WHERE SchemaKey = 'PERSONAL_DB')
BEGIN
    RAISERROR('This database is not marked as the Personal DB. Nothing was changed.', 16, 1);
    SET NOEXEC ON;
END
GO

/* -----------------------------------------------------------------------------
   Tables
   ----------------------------------------------------------------------------- */
IF OBJECT_ID('jobs.CatalogGroups') IS NULL
CREATE TABLE jobs.CatalogGroups
(
    GroupId INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_jobs_CatalogGroups PRIMARY KEY,
    Name    NVARCHAR(100) NOT NULL CONSTRAINT UQ_jobs_CatalogGroups_Name UNIQUE
);
GO

IF OBJECT_ID('jobs.CatalogProfessions') IS NULL
CREATE TABLE jobs.CatalogProfessions
(
    ProfessionId INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_jobs_CatalogProfessions PRIMARY KEY,
    GroupId      INT           NOT NULL CONSTRAINT FK_jobs_CatalogProfessions_Group REFERENCES jobs.CatalogGroups(GroupId),
    Name         NVARCHAR(100) NOT NULL CONSTRAINT UQ_jobs_CatalogProfessions_Name UNIQUE
);
GO

IF OBJECT_ID('jobs.CatalogSkills') IS NULL
CREATE TABLE jobs.CatalogSkills
(
    CatalogSkillId INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_jobs_CatalogSkills PRIMARY KEY,
    Name           NVARCHAR(100) NOT NULL CONSTRAINT UQ_jobs_CatalogSkills_Name UNIQUE
);
GO

IF OBJECT_ID('jobs.CatalogProfessionSkills') IS NULL
CREATE TABLE jobs.CatalogProfessionSkills
(
    ProfessionId   INT NOT NULL CONSTRAINT FK_jobs_CatalogProfessionSkills_Profession REFERENCES jobs.CatalogProfessions(ProfessionId),
    CatalogSkillId INT NOT NULL CONSTRAINT FK_jobs_CatalogProfessionSkills_Skill REFERENCES jobs.CatalogSkills(CatalogSkillId),
    SortOrder      INT NOT NULL,
    CONSTRAINT PK_jobs_CatalogProfessionSkills PRIMARY KEY (ProfessionId, CatalogSkillId)
);
GO

IF OBJECT_ID('jobs.CatalogSubSkills') IS NULL
CREATE TABLE jobs.CatalogSubSkills
(
    CatalogSubSkillId INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_jobs_CatalogSubSkills PRIMARY KEY,
    CatalogSkillId    INT           NOT NULL CONSTRAINT FK_jobs_CatalogSubSkills_Skill REFERENCES jobs.CatalogSkills(CatalogSkillId),
    Name              NVARCHAR(100) NOT NULL,
    SortOrder         INT           NOT NULL,
    CONSTRAINT UQ_jobs_CatalogSubSkills_Skill_Name UNIQUE (CatalogSkillId, Name)
);
GO

/* -----------------------------------------------------------------------------
   The rows of the Excel sheet, first into temporary tables of this session
   ----------------------------------------------------------------------------- */
IF OBJECT_ID('tempdb..#CatGroups') IS NOT NULL DROP TABLE #CatGroups;
IF OBJECT_ID('tempdb..#CatProfessions') IS NOT NULL DROP TABLE #CatProfessions;
IF OBJECT_ID('tempdb..#CatSkills') IS NOT NULL DROP TABLE #CatSkills;
IF OBJECT_ID('tempdb..#CatProfessionSkills') IS NOT NULL DROP TABLE #CatProfessionSkills;
IF OBJECT_ID('tempdb..#CatSubSkills') IS NOT NULL DROP TABLE #CatSubSkills;

CREATE TABLE #CatGroups (Name NVARCHAR(100) NOT NULL);
CREATE TABLE #CatProfessions (GroupName NVARCHAR(100) NOT NULL, Name NVARCHAR(100) NOT NULL);
CREATE TABLE #CatSkills (Name NVARCHAR(100) NOT NULL);
CREATE TABLE #CatProfessionSkills (ProfessionName NVARCHAR(100) NOT NULL, SkillName NVARCHAR(100) NOT NULL, SortOrder INT NOT NULL);
CREATE TABLE #CatSubSkills (SkillName NVARCHAR(100) NOT NULL, Name NVARCHAR(100) NOT NULL, SortOrder INT NOT NULL);
GO

GO

GO

GO

GO

GO

/* -----------------------------------------------------------------------------
   Only what is missing goes into the catalogue
   ----------------------------------------------------------------------------- */
BEGIN TRANSACTION;

SELECT t.Name FROM #CatGroups t
WHERE NOT EXISTS (SELECT 1 FROM jobs.CatalogGroups g WHERE g.Name = t.Name);

SELECT g.GroupId, t.Name
FROM #CatProfessions t
INNER JOIN jobs.CatalogGroups g ON g.Name = t.GroupName
WHERE NOT EXISTS (SELECT 1 FROM jobs.CatalogProfessions p WHERE p.Name = t.Name);

SELECT t.Name FROM #CatSkills t
WHERE NOT EXISTS (SELECT 1 FROM jobs.CatalogSkills s WHERE s.Name = t.Name);

SELECT p.ProfessionId, s.CatalogSkillId, t.SortOrder
FROM #CatProfessionSkills t
INNER JOIN jobs.CatalogProfessions p ON p.Name = t.ProfessionName
INNER JOIN jobs.CatalogSkills s      ON s.Name = t.SkillName
WHERE NOT EXISTS (SELECT 1 FROM jobs.CatalogProfessionSkills x WHERE x.ProfessionId = p.ProfessionId AND x.CatalogSkillId = s.CatalogSkillId);

SELECT s.CatalogSkillId, t.Name, t.SortOrder
FROM #CatSubSkills t
INNER JOIN jobs.CatalogSkills s ON s.Name = t.SkillName
WHERE NOT EXISTS (SELECT 1 FROM jobs.CatalogSubSkills x WHERE x.CatalogSkillId = s.CatalogSkillId AND x.Name = t.Name);

COMMIT TRANSACTION;

DROP TABLE #CatGroups;
DROP TABLE #CatProfessions;
DROP TABLE #CatSkills;
DROP TABLE #CatProfessionSkills;
DROP TABLE #CatSubSkills;
GO

/* =============================================================================
   Procedures
   ============================================================================= */

/* The sub-skills of a catalogue skill, in order. No rows: the skill is not in the catalogue. */
CREATE OR ALTER PROCEDURE jobs.sp_Catalog_SubSkills
    @UserId    INT,
    @SkillName NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    SET @SkillName = LTRIM(RTRIM(ISNULL(@SkillName, '')));

    SELECT u.Name
    FROM jobs.CatalogSubSkills u
    INNER JOIN jobs.CatalogSkills s ON s.CatalogSkillId = u.CatalogSkillId
    WHERE s.Name = @SkillName
    ORDER BY u.SortOrder, u.Name;
END
GO

/* Skill names that start with the text: the catalogue first, then the names that at
   least two people have. Names only. @UserId is taken like everywhere else and is not used. */
CREATE OR ALTER PROCEDURE jobs.sp_Skill_Suggest
    @UserId INT,
    @Query  NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    SET @Query = LTRIM(RTRIM(ISNULL(@Query, '')));
    IF LEN(@Query) < 2 RETURN;

    -- the wildcard characters of LIKE are taken literally
    SET @Query = REPLACE(REPLACE(REPLACE(@Query, '[', '[[]'), '%', '[%]'), '_', '[_]');

    SELECT TOP (10) n.SkillName
    FROM (
        SELECT c.Name AS SkillName, 0 AS Source
        FROM jobs.CatalogSkills c
        WHERE c.Name LIKE @Query + '%'
        UNION
        SELECT s.SkillName, 1 AS Source
        FROM jobs.Skills s
        WHERE s.SkillName LIKE @Query + '%'
        GROUP BY s.SkillName
        HAVING COUNT(DISTINCT s.UserId) >= 2
    ) n
    GROUP BY n.SkillName
    ORDER BY MIN(n.Source), n.SkillName;
END
GO

PRINT 'Job Portal: the catalogue of professions, skills and sub-skills is loaded.';
GO
